# cc-P281: writes the server's guild hall table from design/guild-halls/halls.json, and the tests' byte copy of it.
# Refuses while check.py fails.
#   python -P gen.py [<ShatteredLegacy repo>]         write both files
#   python -P gen.py [<repo>] --verify                 exit 1 if either generated file differs from what it would write
import hashlib
import json
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
args = [a for a in sys.argv[1:] if not a.startswith('--')]
REPO = args[0] if args else 'D:/UO/golems/Iron/ShatteredLegacy'
VERIFY = '--verify' in sys.argv
DESIGN = 'design/guild-halls/halls.json'
DATA_CS = os.path.join(REPO, 'server', 'customizations', 'ClusterFGuildHallPlacementData.cs')
COPY_CS = os.path.join(REPO, 'server', 'tests', 'Misc', 'GuildHallPlacementDesignCopy.cs')
FACINGS = {'North', 'Right', 'East', 'Down', 'South', 'Left', 'West', 'Up'}
SIGN_FACINGS = {'North', 'West'}


def cs(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'


def p3(d):
    return 'new Point3D(%d, %d, %d)' % (d['x'], d['y'], d['z'])


def build():
    text = open(os.path.join(REPO, DESIGN), encoding='ascii').read().replace('\r\n', '\n')
    sha = hashlib.sha256(text.encode('ascii')).hexdigest()
    plan = json.loads(text)
    rows = []
    for h in plan['halls']:
        n, s, t = h['npc'], h['sign'], h['travel']
        assert n['facing'] in FACINGS and s['facing'] in SIGN_FACINGS, h['key']
        b = h.get('building')
        decor = ', '.join('new("%s", "%s", %s)' % (d['set'], d['group'], p3(d)) for d in h.get('decor', []))
        rows.append(
            '        new(%s, %s, Kind.%s, %s, %s, %d,\n'
            '            typeof(%s), %s, Direction.%s,\n'
            '            SignType.%s, SignFacing.%s, %s, %s,\n'
            '            %s, %s,\n'
            '            %d, %s,\n'
            '            [%s])' % (
                cs(h['key']), cs(h['guild']), h['kind'].capitalize(), cs(h['building_name']), cs(h['town']), h['facet'],
                n['type'], p3(n), n['facing'],
                s['type'], s['facing'], p3(s), cs(s['name']),
                p3(t), cs(t['note']),
                b['multi'] if b else 0, p3(b) if b else 'Point3D.Zero',
                decor))
    waits = ',\n'.join('        new(%s, %s, %s)' % (cs(w['key']), cs(w['guild']), cs(w['why'])) for w in plan['waiting'])
    data = f'''// Generated by shard-migration notes/cc-P281-tools/gen.py from {DESIGN}. Do not edit by hand: change the design
// file, run check.py (the map checks) and gen.py. GuildHallPlacementVerification compares this table with the file.
//
// A C# table, not a data file, because the build installs only .cs files from server/customizations (as
// GuildHallDecorTemplates). Points are world tiles on the hall's facet (MapIndex: 0 Felucca, 1 Trammel, 3 Malas,
// 4 Tokuno, 5 Ter Mur).

using Server.Items;
using Server.Mobiles;

namespace Server;

public static class ClusterFGuildHallPlacementData
{{
    public const string DesignFile = "{DESIGN}";
    public const string DesignSha256 = "{sha}";

    /// <summary>Reuse: a free stock building (our sign stands in for its stock sign). Share: stock NPCs stay and our
    /// sign hangs beside theirs. New: OSI's Guild House multi on the survey's plot.</summary>
    public enum Kind
    {{
        Reuse,
        Share,
        New
    }}

    /// <summary>One cc-P265 decor group placed from a world point.</summary>
    public sealed record Decor(string Set, string Group, Point3D At);

    public sealed record Hall(
        string Key, string Guild, Kind Kind, string Building, string Town, int MapIndex,
        System.Type NpcType, Point3D Npc, Direction NpcFacing,
        SignType SignType, SignFacing SignFacing, Point3D Sign, string SignName,
        Point3D Travel, string TravelNote,
        int MultiId, Point3D MultiAt,
        Decor[] Decor
    );

    public sealed record Waiting(string Key, string Guild, string Why);

    public static readonly Hall[] Halls =
    [
{(','+chr(10)).join(rows)}
    ];

    public static readonly Waiting[] Waits =
    [
{waits}
    ];
}}
'''
    copy = f'''// Generated by shard-migration notes/cc-P281-tools/gen.py: a byte copy of {DESIGN} for
// GuildHallPlacementVerification (the test host has no design folder). Do not edit by hand.

namespace ShatteredLegacy.Tests;

public static class GuildHallPlacementDesignCopy
{{
    public const string Sha256 = "{sha}";

    public const string Json = """"
{text.rstrip(chr(10))}
"""";
}}
'''
    return data, copy


def main():
    data, copy = build()
    if VERIFY:
        bad = [p for p, t in ((DATA_CS, data), (COPY_CS, copy))
               if not os.path.exists(p) or open(p, encoding='ascii').read().replace('\r\n', '\n') != t]
        print('differs: %s' % bad if bad else 'generated files match the design file')
        return 1 if bad else 0
    rc = subprocess.call([sys.executable, '-P', os.path.join(HERE, 'check.py')])
    if rc:
        print('refused: check.py fails; nothing written')
        return 1
    for p, t in ((DATA_CS, data), (COPY_CS, copy)):
        with open(p, 'w', encoding='ascii', newline='\n') as f:
            f.write(t)
        print('wrote', p)
    return 0


if __name__ == '__main__':
    sys.exit(main())
